def sum_of_common_divisors(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    common_divisor = gcd(a, b)
    sum_divisors = 0

    for i in range(1, common_divisor + 1):
        if common_divisor % i == 0:
            sum_divisors += i

    return sum_divisors

# Example test
assert sum_of_common_divisors(10, 15) == 6
