def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must have at least two elements")

    # Initialize variables to track the two largest and two smallest numbers
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers

    # Traverse through the array to find the two largest and two smallest numbers
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compare products of the two largest and two smallest numbers
    if max1 * max2 >= min1 * min2:
        return (max1, max2)
    else:
        return (min1, min2)

# Example usage and tests:
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([0, -1, -2, -4, 5, 0, -6]) == (-6, -4)
assert max_Product([-10, -20, 5, 6]) == (-10, -20)
assert max_Product([2, 3]) == (2, 3)
assert max_Product([-1, -2]) == (-1, -2)
