def cal_sum(n):
    def perrin_numbers(n):
        # Generate the first n+1 Perrin numbers
        if n == 0:
            return 3
        elif n == 1:
            return 0
        elif n == 2:
            return 2

        perrin = [3, 0, 2]
        for i in range(3, n + 1):
            perrin.append(perrin[i - 2] + perrin[i - 3])
        return perrin

    # Generate the Perrin numbers and calculate their sum
    perrin = perrin_numbers(n)
    return sum(perrin)

# Example test case
assert cal_sum(9) == 49
